/* prog43_catalan.c
 * Re‑implementation of the original obfuscated binary.
 * Behaviour:
 *   - No argument      -> prints "NO_INPUT"
 *   - Bad argument     -> prints "BAD_INPUT"
 *   - n < 0            -> prints "BAD_INPUT"
 *   - n > 30           -> prints "OUT_OF_RANGE"
 *   - 0 ≤ n ≤ 30       -> prints the n‑th Catalan number (C_n) and a newline
 *
 * The program never reads from stdin and always returns 0.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

static long long catalan(int n)
{
    /* n is guaranteed to be in [0,30] */
    unsigned long long cat[31];
    cat[0] = 1ULL;
    for (int i = 1; i <= n; ++i) {
        unsigned long long sum = 0ULL;
        for (int j = 0; j < i; ++j) {
            sum += cat[j] * cat[i - 1 - j];
        }
        cat[i] = sum;
    }
    return (long long)cat[n];
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long val = strtol(argv[1], &endptr, 10);

    /* No digits were found */
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }
    /* Extra characters after the number */
    if (*endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    /* Detect overflow/underflow from strtol */
    if ((errno == ERANGE && (val == LONG_MAX || val == LONG_MIN)) ||
        val > INT_MAX || val < INT_MIN) {
        puts("BAD_INPUT");
        return 0;
    }

    int n = (int)val;
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 30) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    printf("%lld\n", catalan(n));
    return 0;
}
